dashboard.definition:
{
  "visualizations": {
    "viz_dta_export_success": {
      "type": "splunk.table",
      "title": "Export / External Media Write — Success",
      "dataSources": { "primary": "ds_dta_export_success" },
      "options": { "dataOverlayMode": "none", "count": 100, "drilldown": "row" }
    },
    "viz_dta_export_failure": {
      "type": "splunk.table",
      "title": "Export / External Media Write — Failure",
      "dataSources": { "primary": "ds_dta_export_failure" },
      "options": { "dataOverlayMode": "none", "count": 100, "drilldown": "row" }
    },
    "viz_dta_import_success": {
      "type": "splunk.table",
      "title": "Import / External Media Read — Success",
      "dataSources": { "primary": "ds_dta_import_success" },
      "options": { "dataOverlayMode": "none", "count": 100, "drilldown": "row" }
    },
    "viz_dta_import_failure": {
      "type": "splunk.table",
      "title": "Import / External Media Read — Failure",
      "dataSources": { "primary": "ds_dta_import_failure" },
      "options": { "dataOverlayMode": "none", "count": 100, "drilldown": "row" }
    }
  },
  "dataSources": {
    "ds_dta_export_success": {
      "type": "ds.search",
      "options": {
        "query": "| savedsearch stig_dta_external_media_write_success_linux | append [| savedsearch stig_dta_export_success_cisco] | append [| savedsearch stig_dta_config_export_success_pan] | search source_type=$source_filter:value$ | table _time event_category event_action source_host source_type outcome user details | sort -_time",
        "queryParameters": { "earliest": "$global_time.earliest$", "latest": "$global_time.latest$" }
      },
      "name": "DTA Export Success (all sources)"
    },
    "ds_dta_export_failure": {
      "type": "ds.search",
      "options": {
        "query": "| savedsearch stig_dta_external_media_write_failure_linux | append [| savedsearch stig_dta_export_failure_cisco] | append [| savedsearch stig_dta_config_export_fail_pan] | search source_type=$source_filter:value$ | table _time event_category event_action source_host source_type outcome user details | sort -_time",
        "queryParameters": { "earliest": "$global_time.earliest$", "latest": "$global_time.latest$" }
      },
      "name": "DTA Export Failure (all sources)"
    },
    "ds_dta_import_success": {
      "type": "ds.search",
      "options": {
        "query": "| savedsearch stig_dta_external_media_read_success_linux | append [| savedsearch stig_dta_import_success_cisco] | append [| savedsearch stig_dta_config_import_success_pan] | search source_type=$source_filter:value$ | table _time event_category event_action source_host source_type outcome user details | sort -_time",
        "queryParameters": { "earliest": "$global_time.earliest$", "latest": "$global_time.latest$" }
      },
      "name": "DTA Import Success (all sources)"
    },
    "ds_dta_import_failure": {
      "type": "ds.search",
      "options": {
        "query": "| savedsearch stig_dta_import_failure_cisco | append [| savedsearch stig_dta_config_import_fail_pan] | search source_type=$source_filter:value$ | table _time event_category event_action source_host source_type outcome user details | sort -_time",
        "queryParameters": { "earliest": "$global_time.earliest$", "latest": "$global_time.latest$" }
      },
      "name": "DTA Import Failure (cisco + pan; no linux signal)"
    }
  },
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time Range",
      "options": { "token": "global_time", "defaultValue": "-24h@h,now" }
    },
    "input_source": {
      "type": "input.dropdown",
      "title": "Source",
      "options": {
        "token": "source_filter",
        "defaultValue": "*",
        "items": [
          { "label": "All", "value": "*" },
          { "label": "linux", "value": "linux" },
          { "label": "cisco", "value": "cisco" },
          { "label": "paloalto", "value": "paloalto" }
        ]
      }
    }
  },
  "layout": {
    "type": "absolute",
    "options": { "width": 1440, "height": 900, "display": "auto" },
    "structure": [
      { "item": "input_time", "type": "input", "position": { "x": 0, "y": 0, "w": 720, "h": 60 } },
      { "item": "input_source", "type": "input", "position": { "x": 720, "y": 0, "w": 720, "h": 60 } },
      { "item": "viz_dta_export_success", "type": "block", "position": { "x": 0, "y": 70, "w": 720, "h": 400 } },
      { "item": "viz_dta_export_failure", "type": "block", "position": { "x": 720, "y": 70, "w": 720, "h": 400 } },
      { "item": "viz_dta_import_success", "type": "block", "position": { "x": 0, "y": 480, "w": 720, "h": 400 } },
      { "item": "viz_dta_import_failure", "type": "block", "position": { "x": 720, "y": 480, "w": 720, "h": 400 } }
    ]
  },
  "title": "STIG - Data Transfer (DTA) Events",
  "description": "Data Transfer events across RHEL9, Cisco, Palo Alto.",
  "defaults": {
    "dataSources": {
      "ds.search": { "options": { "queryParameters": { "earliest": "$global_time.earliest$", "latest": "$global_time.latest$" } } }
    }
  }
}
